mapper.sql:
FROM yc_collection_item i LEFT JOIN yc_collection_series s ON s.id = i.series_id WHERE i.status = 1 AND i.deleted_at IS NULL AND i.is_on_shelf = 1
AND i.series_id = #{seriesId}
AND ( i.name LIKE CONCAT('%', #{keyword}, '%') OR i.item_code LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT i.id, i.item_code, i.series_id, i.name, i.rarity_level, i.cover_url, i.model_url, i.model_format, i.description, i.is_on_shelf, i.status, i.created_by, i.updated_by, i.created_at, i.updated_at, i.deleted_at, s.name AS series_name, s.series_code AS series_code, CASE WHEN uc.id IS NULL THEN 0 ELSE 1 END AS collected, uc.acquired_at FROM yc_collection_item i LEFT JOIN yc_collection_series s ON s.id = i.series_id LEFT JOIN yc_user_collection uc ON uc.item_id = i.id AND uc.user_id = #{userId} WHERE i.status = 1 AND i.deleted_at IS NULL AND i.is_on_shelf = 1
AND i.series_id = #{seriesId}
AND ( i.name LIKE CONCAT('%', #{keyword}, '%') OR i.item_code LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY i.rarity_level DESC, i.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM yc_user_collection
WHERE user_id = #{userId}
  AND item_id = #{itemId}

mapper.delete:
DELETE FROM yc_user_collection
WHERE user_id = #{userId}
  AND item_id = #{itemId}
  AND acquire_type = 'favorite'

mapper.update:
UPDATE yc_redeem_code
SET status = #{status},
    used_by_user_id = #{usedByUserId},
    used_at = #{usedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(1)
FROM yc_user_collection
WHERE item_id = #{itemId}

mapper.update:
UPDATE yc_collection_item
SET
    is_on_shelf = #{isOnShelf},
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND deleted_at IS NULL

mapper.select:
SELECT i.id, i.item_code, i.series_id, i.name, i.rarity_level, i.cover_url, i.model_url, i.model_format, i.description, i.is_on_shelf, i.status, i.created_by, i.updated_by, i.created_at, i.updated_at, i.deleted_at, s.name AS series_name, s.series_code AS series_code FROM yc_collection_item i LEFT JOIN yc_collection_series s ON s.id = i.series_id WHERE i.deleted_at IS NULL
AND i.series_id = #{seriesId}
AND i.status = #{status}
AND i.is_on_shelf = #{isOnShelf}
ORDER BY i.updated_at DESC, i.id DESC

SELECT rc.id, rc.code, rc.item_id, rc.issued_channel, rc.expire_at, rc.status, rc.used_by_user_id, rc.used_at, rc.created_at, rc.updated_at, i.name AS item_name, COALESCE(u.display_name, u.username, CONCAT('用户', rc.used_by_user_id)) AS used_by_name FROM yc_redeem_code rc LEFT JOIN yc_collection_item i ON i.id = rc.item_id LEFT JOIN yc_user_account u ON u.id = rc.used_by_user_id WHERE 1 = 1
AND rc.status = #{status}
AND rc.item_id = #{itemId}
ORDER BY rc.created_at DESC, rc.id DESC

SELECT p.id, p.user_id, p.ai_work_id, COALESCE(u.display_name, u.username, CONCAT('用户', p.user_id)) AS author_name, p.title, p.content_html, p.summary, p.category, p.tags, p.cover_image, p.status, p.like_count, p.comment_count, p.created_at, p.updated_at FROM yc_community_post p LEFT JOIN yc_user_account u ON u.id = p.user_id WHERE p.status = 1
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%') OR p.content_html LIKE CONCAT('%', #{keyword}, '%') )
AND p.category = #{category}
AND p.tags LIKE CONCAT('%', #{tag}, '%')
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE yc_ai_model_work
SET generation_status = 'RUNNING', updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND generation_status IN ('SUBMITTED', 'RUNNING')

UPDATE yc_ai_model_work
SET generation_status = 'FAILED', last_error = #{lastError},
    generation_charge_status = #{chargeStatus}, updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND generation_status IN ('SUBMITTED', 'RUNNING')

UPDATE yc_ai_model_work
SET storage_status = 'PERMANENT', model_url = #{ossUrl}, oss_url = #{ossUrl}, cover_url = #{coverUrl}, persisted_at = NOW(),
    model_size_bytes = #{modelSizeBytes}, last_error = NULL, updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND storage_status = 'PERSISTING'

UPDATE yc_ai_model_work
SET storage_status = 'PERSIST_FAILED', persist_charge_status = #{chargeStatus},
    last_error = #{lastError}, updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND storage_status = 'PERSISTING'

UPDATE yc_ai_model_work
SET storage_status = 'PERSIST_FAILED',
    persist_charge_status = #{chargeStatus},
    last_error = #{lastError},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND storage_status = 'PERSISTING'
  AND persist_started_at IS NOT NULL
  AND persist_started_at <= #{cutoff}
